import React from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

const CrimeStats = ({ crimes }) => {
  if (!crimes || crimes.length === 0) return <div>No data available.</div>;

  const totalCrimes = crimes.reduce((acc, c) => acc + (c.Total_Incidents || 1), 0);

  return (
    <div>
      <h2>Crime Statistics</h2>
      <p>Total Crimes: {totalCrimes}</p>

      <ResponsiveContainer width="100%" height={300}>
        <BarChart data={crimes}>
          <XAxis dataKey="CrimeCode" />
          <YAxis />
          <Tooltip />
          <Bar dataKey="Total_Incidents" fill="#8884d8" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
};

export default CrimeStats;
